using namespace Snatcher;
namespace {unsigned checks;void check(bool v,const char* why){++checks;if(!v){std::fprintf(stderr,"Gens failure %u: %s\n",checks,why);std::exit(1);}}
FmInstrument tone(){FmInstrument v={};v.source[0]=7;v.algorithm=7;for(unsigned op=0;op<4;++op){auto p=v.source+1+6*op;p[0]=1;p[1]=24;p[2]=31;p[5]=15;}return v;}
void start(GensFmSynthRenderer& s,unsigned c,uint8_t pan,std::string& e){uint8_t l[4]={24,24,24,24};check(s.instrument(c,tone(),e)&&s.pan(c,pan,e)&&s.frequency(c,0x2400,e)&&s.levels(c,l,e)&&s.key(c,true,e),e.c_str());}
}
int main(int argc,char** argv){std::string e;FmCore c;check(parseFmCore("gens",c)&&c==kFmGens&&parseFmCore("nuked",c)&&c==kFmNuked&&!parseFmCore("unknown",c),"explicit backend names");check(fmHistoryFramesAllowed(8,3810240000)&&fmHistoryEventsAllowed(8,65536)&&!fmHistoryFramesAllowed(9,0),"Gens bounded history");
GensFmSynthRenderer unloaded;std::vector<uint8_t> pristine;check(unloaded.snapshotState(pristine,e),"unloaded owner has a valid zero-state checkpoint");check(unloaded.restoreState(pristine,e,0),e.c_str());
for(bool coupled:{false,true})for(uint32_t rate:{8000u,44100u,48000u,192000u}){
 GensFmSynthRenderer s(rate,coupled),cold(rate,coupled);check(s.reset(e),e.c_str());std::vector<int16_t> a,b;check(s.renderPcm(17,a,e)&&std::all_of(a.begin(),a.end(),[](int16_t x){return x==0;}),"reset silence");
 for(unsigned ch=0;ch<6;++ch){check(s.reset(e),e.c_str());start(s,ch,0x80,e);check(s.keyOnMask()==(1u<<ch),"all six key/register banks routed");check(s.renderPcm(1024,a,e),e.c_str());bool sound=false;for(size_t i=0;i<a.size();i+=2){sound|=a[i]!=0;check(a[i+1]==0,"left-only stereo samples");}check(sound,"each voice generates samples");check(s.fastRelease(ch,e)&&s.keyOnMask()==0,"release clears source key");}
 check(s.reset(e),e.c_str());for(unsigned ch=0;ch<6;++ch)start(s,ch,0xc7,e);check(s.lfo(15,e),e.c_str());
 for(unsigned prefix:{0u,1u,17u,735u,736u,4096u}){if(prefix)check(s.renderPcm(prefix,a,e),e.c_str());std::vector<uint8_t> state,before,after;check(s.snapshotState(state,e)&&cold.restoreState(state,e),e.c_str());check(s.renderPcm(4411,a,e)&&cold.renderPcm(4411,b,e)&&a==b,"cold scalar continuation exact for six modulated voices");check(cold.snapshotState(before,e),e.c_str());auto scalarBad=state;const size_t scalarAt=5+std::string("8238afd9503a59ffcec0e2685584d5ce819ad7c6:gens-state1").size()+4+8+1+1+32+4;for(unsigned i=0;i<4;++i)scalarBad[scalarAt+i]=255;uint64_t sum=UINT64_C(14695981039346656037);for(size_t i=0;i<scalarBad.size()-8;++i)sum=(sum^scalarBad[i])*UINT64_C(1099511628211);for(unsigned i=0;i<8;++i)scalarBad[scalarBad.size()-8+i]=uint8_t(sum>>((7-i)*8));check(!cold.restoreState(scalarBad,e)&&cold.snapshotState(after,e)&&before==after,"range-invalid scalar rejects despite repaired checksum");for(size_t at:{size_t(0),size_t(4),state.size()/2,state.size()-1}){auto bad=state;bad[at]^=1;check(!cold.restoreState(bad,e)&&cold.snapshotState(after,e)&&before==after,"corruption rejected transactionally");}check(!cold.restoreState(state,e,s.renderedFrames()+1),"wrong frame owner rejected");NativeFmSynthRenderer nuked(rate,coupled);check(!nuked.restoreState(state,e),"Gens state cannot become Nuked");GensFmSynthRenderer wrong(rate==44100?48000:44100,coupled);check(!wrong.restoreState(state,e),"sample rate mismatch rejected");}
 GensFmSynthRenderer whole(rate,coupled),parts(rate,coupled);start(whole,0,0xc0,e);start(parts,0,0xc0,e);check(whole.renderPcm(4096,a,e),e.c_str());std::vector<int16_t> joined;for(unsigned n:{1u,17u,735u,736u,2607u}){check(parts.renderPcm(n,b,e),e.c_str());joined.insert(joined.end(),b.begin(),b.end());}check(a==joined,"callback partition invariant");check(!parts.renderPcm(0,b,e)&&!parts.key(6,true,e),"invalid requests reject");
}
for(int i=1;i<argc;++i){std::ifstream file(argv[i],std::ios::binary);std::vector<uint8_t> saved((std::istreambuf_iterator<char>(file)),{});check(bool(file)&&saved.size()>80,"owner NFG fixture");size_t at=5+std::string("8238afd9503a59ffcec0e2685584d5ce819ad7c6:gens-state1").size();uint32_t rate=0;for(unsigned j=0;j<4;++j)rate=rate<<8|saved[at++];at+=8+1;bool coupled=saved[at]!=0;GensFmSynthRenderer a(rate,coupled),b(rate,coupled);check(a.restoreState(saved,e)&&b.restoreState(saved,e),e.c_str());std::vector<uint8_t> exact;check(a.snapshotState(exact,e)&&exact==saved,"owner scalar state preserved exactly");std::vector<int16_t> whole,first,second;check(a.renderPcm(1471,whole,e)&&b.renderPcm(735,first,e)&&b.renderPcm(736,second,e),e.c_str());first.insert(first.end(),second.begin(),second.end());check(whole==first,"owner released-envelope future PCM deterministic");}
GensFmSynthRenderer invalid(0);check(!invalid.init(e),"invalid rate rejected");std::printf("Gens: %u checks, 0 failures\n",checks);}
